def q(key,level,prompt,opts,explanation,sids,subject,sk,prop,objective,topic='prevention',category='quality',article='ref-resines-extraits',jurisdiction=None):
    sids=[sids] if isinstance(sids,str) else sids
    ans=len(questions)%4
    options=list(opts);correct=options.pop(0);options.insert(ans,correct)
    ed=dict(domain='active',category=category,subject=subject,subjectKey=sk,property=prop,expectedAnswer=correct,learningObjective=objective,factKey=key,form='identification',difficultyRationale={1:'Repère concret de culture ou d’objet, reconnaissable sans notion technique spécialisée.',2:'Connaissance précise d’un produit, d’un récit historique ou d’une règle nationale.',3:'Résultat pharmacocinétique ou observation scientifique circonscrite demandant une distinction spécialisée.'}[level],sourceEvidence=[dict(sourceId=sid,locator=next(x for x in sources if x['id']==sid)['consultation']['locator'],support=next(x for x in sources if x['id']==sid)['passage']) for sid in sids])
    if jurisdiction:ed.update(jurisdiction=jurisdiction,reviewAfter='2027-05-17',verifiedAsOf=DAY)
    questions.append(dict(id='hemp-q2-rp05-'+key,topicId=topic,level=level,prompt=prompt,options=options,answer=ans,explanation=explanation,articleId=article,sourceIds=sids,editorial=ed))

q('cbd-increases-caffeine-exposure',3,'Dans l’essai de Thai (2021), quel effet le CBD pharmaceutique avait-il sur la caféine ?',['Il augmentait l’exposition et ralentissait son élimination','Il diminuait l’exposition et accélérait son élimination','Il empêchait son absorption digestive','Il ne modifiait pas son devenir dans l’organisme'],'L’essai observe une exposition accrue à la caféine, cohérente avec une inhibition du CYP1A2. Ce résultat pharmacocinétique ne prédit pas à lui seul les symptômes de chaque consommateur.',CAF,'CBD et caféine','cbd-caffeine-interaction','Exposition accrue à la caféine','Reconnaître une interaction pharmacocinétique propre au CBD.',category='prevention',article='ref-cbd',jurisdiction='Essai humain2021 sur CBD pharmaceutique')
q('rifampin-decreases-cbd-exposure',3,'Selon la notice FDA de2026, comment la rifampicine modifie-t-elle l’exposition au CBD pharmaceutique et au7-OH-CBD ?',['Elle diminue les deux','Elle augmente les deux','Elle augmente le CBD et diminue le7-OH-CBD','Elle diminue le CBD et augmente le7-OH-CBD'],'La rifampicine stimule des enzymes qui interviennent dans le devenir du CBD et réduit l’exposition au CBD et au7-OH-CBD. Il s’agit d’une interaction de médicament, sans consigne d’ajustement personnel.',RIF,'Rifampicine et CBD','cbd-rifampin-interaction','Diminution de l’exposition au CBD','Distinguer une interaction réduisant l’exposition de celles qui l’augmentent.',category='prevention',article='ref-cbd',jurisdiction='États-Unis, notice FDA mai2026')
q('sebsi-wood-clay-materials',2,'Quels matériaux composent traditionnellement le sebsi marocain décrit par le Hash Museum ?',['Une tige en bois et un foyer en argile','Une tige en métal et un foyer en verre','Une tige en roseau et un foyer en pierre','Une tige en verre et un foyer en bois'],'Cette longue pipe fine associe une tige en bois à un petit foyer d’argile. Le sebsi appartient à la culture marocaine du kif ; il se distingue des pipes à réservoir d’eau.',SEB,'Pipe sebsi','sebsi-pipe','Tige bois et foyer argile','Reconnaître les matériaux d’un objet traditionnel lié au kif.',topic='history',category='history',article='ref-histoire-culture')
q('malana-cream-himachal-origin',2,'À quelle région le NCB indien rattache-t-il le haschich appelé « Malana Cream » ?',['L’Himachal Pradesh, autour de Malana et Kullu','Le Rif, autour de Chefchaouen','La Bekaa, autour de Baalbek','L’Hindu Kush, autour de Mazar-e-Charif'],'Le communiqué situe Malana dans la vallée de Parvati et le district de Kullu, en Himachal Pradesh. Cette indication géographique ne certifie pas l’origine de tout produit vendu sous ce nom.',MAL,'Malana Cream','malana-cream','Ancrage géographique en Himachal Pradesh','Situer une appellation de résine sans en faire une certification.',topic='history',category='history',article='ref-histoire-culture')
q('chemdog-grateful-dead-concert',2,'Selon le récit de Greg Krzanowski, un concert de quel groupe est lié à l’histoire de Chemdog en1991 ?',['Grateful Dead','Pink Floyd','The Rolling Stones','Santana'],'Krzanowski raconte avoir acheté le cannabis à l’origine de cette histoire lors d’un concert du Grateful Dead. Ce témoignage situe un récit de circulation du cannabis ; il ne prouve pas un pedigree.',CHE,'Histoire de Chemdog','chemdog-chem91-history','Concert du Grateful Dead','Relier une lignée à un récit documenté de culture musicale.',topic='history',category='history',article='ref-noms-lignees')
q('chronic-ak47-pedigree',2,'Quelle lignée Serious Seeds cite-t-il aux côtés de Northern Light et Northern Light/Skunk dans l’ascendance de Chronic ?',['AK-47','White Widow','Haze','Blueberry'],'Le pedigree revendiqué par Serious Seeds réunit AK-47, Northern Light et un croisement Northern Light/Skunk. Il s’agit d’une attribution d’obtenteur, sans validation génétique indépendante.',CHR,'Chronic','chronic','AK-47 dans le pedigree revendiqué','Lire une parenté précise attribuée à un obtenteur externe.',topic='genetics',category='varieties',article='ref-noms-lignees')
