    for x in questions:
        assert len(x['id'])<=75
        assert len(x['prompt'])<=150,(x['id'],'prompt',len(x['prompt']))
        assert len(x['explanation'])<=240,(x['id'],'explanation',len(x['explanation']))
        assert len(set(x['options']))==4
        assert all(len(o)<=75 for o in x['options']),(x['id'],'options',[(len(o),o) for o in x['options']])
        assert x['articleId'] in article_ids,x['articleId']
    batch=dict(batchId='r-products-05',author=AUTHOR,role='Produits, objets, culture des usages et interactions du cannabis',questions=questions,sources=sources)
    (ROOT/'batches/r-products-05.json').write_text(json.dumps(batch,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    facts=dict(batchId='r-products-05',author=AUTHOR,createdAt=DAY,status='author-frozen-awaiting-independent-review',count=27,domain='active',levels=dict(Counter(str(x['level']) for x in questions)),
      contributions=[dict(researcher='rebalance_classify_b',scope='Sources Rick James et full melt ; rédaction des questions par Sol, relecture indépendante A requise.',record='docs/quiz-2000/facts/rp05-cultural-research-b.json')],
      sourcesRead=[dict(sourceId=x['id'],url=x['url'],access=x['access'],reader=x['consultation']['reader'],locator=x['consultation']['locator']) for x in sources],
      neighbourAudit=dict(index='docs/quiz-2000/fact-index.jsonl',excludedCandidates=['Dr Grinspoon fleurs en perles : rb05 exact.','Hempfest ville et mission politique : rb02 et explication Hash Bash.','Benjamin On Hashish et Dumas Franz : rb03 exacts.','Lennon/John Sinclair : rb02.','CBN par oxydation : fait historique conservé.'],
      openedNeighbours=['hemp-hc-052','hemp-q2-ra03-portugal-personal-cannabis-possession-administrative','hemp-q2-rb05-grinspoon-fleurs-perles','hemp-q2-rb05-kif-melange-marocain','hemp-q2-rb03-benjamin-notes-haschisch','hemp-q2-rb03-dumas-franz-haschisch'],
      distinctions=['Portugal : pénalisation de la culture personnelle, absent de la question possession/vente ra03.','Dawamesk : forme de préparation, absent de l’explication Balzac examinant puis refusant.','Sebsi : matériaux bois/argile, absent de rb05 qui ne décrit qu’une pipe.','Chemdog : concert Grateful Dead distinct de l’identité de Krzanowski ra06 ; clé commune.','OCS : cristallisation du CBD et sens de la connexion510 sont deux propriétés distinctes.','Full melt : une seule question, pas de variante six étoiles.']),
      facts=[dict(id=x['id'],factKey=x['editorial']['factKey'],subjectKey=x['editorial']['subjectKey'],expectedAnswer=x['editorial']['expectedAnswer']) for x in questions])
    (ROOT/'facts/r-products-05.json').write_text(json.dumps(facts,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print(json.dumps(dict(questions=27,sources=len(sources),levels=facts['levels'])))
